// The nine works shown on the site, taken from the shared works data
// (js/data/works.js, generated by tools/build_works.py). No categories:
// each opens straight into its own project page.
//   - Ergon Xlu is one project: the live website, then the brand work.
//   - Every social-media client shares one card, shown as a mixed grid.
import { WORKS } from './data/works.js?v=81';

const find = (cat, id) => WORKS[cat].find((x) => x.id === id);
const imgs = (w) => (w.images || []).map((im) => ({ ...im }));

function work(cat, id, kind, extra = {}) {
  const w = find(cat, id);
  const meta = w.meta || [w.industry, ...(w.deliverables || [])].filter(Boolean);
  return {
    id,
    title: w.title || w.name,
    kind,
    desc: w.desc || w.sub || kind,
    meta: meta.slice(0, 4),
    live: w.live || null,
    liveKind: w.kind === 'site' ? 'site' : w.live ? 'proto' : null,
    images: imgs(w),
    ...extra,
  };
}

const ergonSite = find('ui', 'ergonxlu'), ergonBrand = find('brand', 'ergon');
const social = WORKS.social;

const LIST = [
  work('ui', 'oaks-dashboard', 'UI / UX · Dashboard'),
  work('brand', 'gaurav', 'Brand & Packaging'),
  work('game', 'elixir', 'Game Art'),
  work('ui', 'coldtrace', 'Product Design'),
  work('art', 'p7', 'Logo & Print'),
  work('brand', 'momma', 'Packaging System'),
  {
    id: 'social',
    title: 'Social Media',
    kind: 'Campaigns · Posts · Reels covers',
    desc: `Post and campaign design for ${social.length} brands: ${social.map((s) => s.title || s.name).join(', ')}. Grids planned as a set, each post built to stop the scroll and still read at a glance.`,
    meta: ['Instagram & LinkedIn', 'Campaign systems', 'Festive & launch posts', `${social.reduce((n, s) => n + (s.images || []).length, 0)} creatives`],
    live: null,
    liveKind: null,
    groups: social.map((s) => ({ title: s.title || s.name, images: imgs(s) })),
    images: social.flatMap(imgs),
  },
  {
    id: 'ergonxlu',
    title: 'Ergon Xlu',
    kind: 'Website & Brand',
    desc: `${ergonSite.desc} ${ergonBrand.desc || ''}`.trim(),
    meta: ['Website design', 'Brand identity', 'Product catalogue', 'Premium seating'],
    live: ergonSite.live,
    liveKind: 'site',
    images: [...imgs(ergonSite), ...imgs(ergonBrand)],
  },
  work('art', 'fibril', 'Packaging & Print'),
];

export const PROJECTS = LIST.map((p, i) => ({ ...p, no: String(i + 1).padStart(2, '0'), cover: p.images[0] }));
